const j = $input.item.json;
const lane = String(j.Lane || j.lane || 'mix');
const model = j.gemini_model || 'gemini-2.5-flash';
const key = $env.GEMINI_API_KEY;
if (!key) {
  throw new Error('Set GEMINI_API_KEY in n8n env / Windows environment variables');
}
const prompt = `You are the content strategist for LOOP WORK, a channel about AI automation (n8n), website design, and digital marketing.\nGive 10 high-performing faceless Shorts/Reels ideas.\nLane: ${lane}\nEach idea must have a sharp hook, a specific promise, and a visual mix (Pexels b-roll + AI stills).\nReturn JSON only: {"ideas":[{"title":"","hook":"","format":"reel","lane":"","why_it_will_perform":"","pexels_query":"","ai_image_prompt":""}]}`;
return [{
  json: {
    url: `https://generativelanguage.googleapis.com/v1beta/models/${model}:generateContent?key=${key}`,
    body: {
      contents: [{ role: 'user', parts: [{ text: prompt }] }],
      generationConfig: { temperature: 0.9, responseMimeType: 'application/json' }
    }
  }
}];

const text = $input.item.json.candidates[0].content.parts[0].text;
const cleaned = text.replace(/^```json\s*/i, '').replace(/\s*```$/, '').trim();
const pack = JSON.parse(cleaned);
return (pack.ideas || []).map((idea, i) => ({ json: { n: i + 1, ...idea } }));
